"""Document properties carried from the uploaded CV onto its tailored exports.

The feature is one the candidate never sees unless it goes wrong, and every way it goes
wrong is silent — a properties dialog is the only place the damage shows. So the bars here
are about what the exported file *claims*:

  * the renderer's fingerprints (``ReportLab PDF Library``, "generated by python-docx") do
    not survive into anything the candidate sends;
  * python-docx's 2013-12-23 template date never reaches an export, mirrored or not — it
    is the one value that is wrong under every reading;
  * an original with no readable properties degrades to neutral, honest values rather than
    to a library default or an invention;
  * stamping rewrites the properties and nothing else: the page content a recruiter (or an
    ATS) reads must come through byte-for-byte.

Fully offline — no Postgres, no MCP, no model.
"""

from __future__ import annotations

import io
from datetime import datetime, timezone

import pytest
from jobpilot_core import doc_meta, tailor

BASE = {
    "contact": {"name": "Jane Doe", "email": "jane@example.com"},
    "summary": "Backend engineer.",
    "skills": ["Go", "Kubernetes"],
    "experience": [{"title": "Engineer", "company": "Acme", "dates": "2020-2024",
                    "bullets": ["Shipped the thing."]}],
    "education": ["BSc Computer Science"],
    "certifications": [],
    "projects": [],
    "additional_sections": [],
}

WORD_PROPS = {
    "/Producer": "Microsoft Word for Microsoft 365",
    "/Creator": "Microsoft Word",
    "/Author": "Jane A. Doe",
    "/Title": "Jane Doe CV 2024",
    "/Subject": "Curriculum Vitae",
    "/Keywords": "engineer, golang",
    "/CreationDate": "D:20240115091500+00'00'",
}


def _pdf_props(data: bytes) -> dict:
    from pypdf import PdfReader

    return dict(PdfReader(io.BytesIO(data)).metadata or {})


def _docx_props(data: bytes):
    import docx

    return docx.Document(io.BytesIO(data)).core_properties


def _upload_pdf(props: dict | None = None) -> bytes:
    """A stand-in for an uploaded CV: a PDF carrying the given document properties."""
    from pypdf import PdfWriter

    writer = PdfWriter(clone_from=io.BytesIO(tailor.render_pdf(BASE)))
    writer.add_metadata(props if props is not None else WORD_PROPS)
    buf = io.BytesIO()
    writer.write(buf)
    return buf.getvalue()


def _upload_docx(**props) -> bytes:
    import docx

    document = docx.Document()
    document.add_paragraph("Jane Doe")
    for key, value in props.items():
        setattr(document.core_properties, key, value)
    buf = io.BytesIO()
    document.save(buf)
    return buf.getvalue()


# --------------------------------------------------------------------------- #
# Reading the original
# --------------------------------------------------------------------------- #
def test_reads_a_pdf_originals_properties():
    meta = doc_meta.read_doc_metadata(_upload_pdf())
    assert meta["producer"] == "Microsoft Word for Microsoft 365"
    assert meta["creator"] == "Microsoft Word"
    assert meta["author"] == "Jane A. Doe"
    assert meta["title"] == "Jane Doe CV 2024"
    assert meta["subject"] == "Curriculum Vitae"
    assert meta["created"] == datetime(2024, 1, 15, 9, 15, tzinfo=timezone.utc)


def test_reads_a_docx_originals_properties():
    meta = doc_meta.read_doc_metadata(
        _upload_docx(author="Jane A. Doe", title="CV", subject="Curriculum Vitae"))
    assert meta["author"] == "Jane A. Doe"
    assert meta["title"] == "CV"
    # A DOCX records no authoring application in core properties, so there is nothing
    # honest to put in /Producer and the PDF export must not invent one.
    assert "producer" not in meta and "creator" not in meta


@pytest.mark.parametrize("data", [b"", b"not a document at all", b"%PDF-1.4 truncated"])
def test_an_unreadable_original_yields_nothing_rather_than_raising(data):
    """Best effort by contract: the export is the deliverable, its properties are a nicety."""
    assert doc_meta.read_doc_metadata(data) == {}


def test_renderer_placeholders_are_not_carried_forward():
    """reportlab writes '(unspecified)' and python-docx 'generated by python-docx' when the
    caller sets nothing. Mirroring one onto the next export would launder a tool's default
    into a claim about the candidate's document, and it compounds every round trip."""
    meta = doc_meta.read_doc_metadata(_upload_pdf({
        "/Producer": "", "/Creator": "(unspecified)", "/Subject": "(unspecified)",
        "/Author": "Jane Doe"}))
    assert "creator" not in meta and "subject" not in meta and "producer" not in meta
    assert meta["author"] == "Jane Doe"

    docx_meta = doc_meta.read_doc_metadata(_upload_docx(comments="generated by python-docx"))
    assert "comments" not in docx_meta


def test_the_python_docx_template_date_is_never_carried():
    """python-docx stamps 2013-12-23 on every document it creates. A CV that went out
    through this pipeline once already carries it, so re-reading one must not treat it as
    the candidate's real creation date and mirror it onward."""
    meta = doc_meta.read_doc_metadata(_upload_docx(author="Jane Doe"))
    assert "created" not in meta
    assert doc_meta.read_doc_metadata(_upload_docx(
        created=datetime(2013, 12, 23, 23, 15, tzinfo=timezone.utc))).get("created") is None


def test_reading_does_not_touch_the_original_bytes():
    original = _upload_pdf()
    before = bytes(original)
    doc_meta.read_doc_metadata(original)
    assert original == before


# --------------------------------------------------------------------------- #
# Resolving — mirror where there is something to mirror, neutral elsewhere
# --------------------------------------------------------------------------- #
def test_neutral_fallback_uses_the_candidates_name_and_a_real_now():
    now = datetime(2026, 5, 1, 12, 0, tzinfo=timezone.utc)
    resolved = doc_meta.resolve({}, name="Jane Doe", now=now)
    assert resolved["author"] == "Jane Doe" and resolved["title"] == "Jane Doe"
    assert resolved["created"] == now and resolved["modified"] == now
    assert "producer" not in resolved  # nothing to claim, so claim nothing


def test_the_originals_properties_win_over_the_name_default():
    resolved = doc_meta.resolve({"author": "Jane A. Doe", "title": "CV 2024"}, name="Jane Doe")
    assert resolved["author"] == "Jane A. Doe" and resolved["title"] == "CV 2024"


def test_modified_is_now_even_when_creation_is_mirrored():
    """An edited document has an old creation date and a recent modification date. Mirroring
    both would claim the file has not been touched since the original was written, which is
    the one part of the story that is plainly untrue of a freshly tailored CV."""
    now = datetime(2026, 5, 1, 12, 0, tzinfo=timezone.utc)
    created = datetime(2024, 1, 15, 9, 15, tzinfo=timezone.utc)
    resolved = doc_meta.resolve({"created": created, "modified": created}, name="J", now=now)
    assert resolved["created"] == created and resolved["modified"] == now


# --------------------------------------------------------------------------- #
# Stamping the exports
# --------------------------------------------------------------------------- #
def test_a_tailored_pdf_carries_the_originals_properties():
    meta = doc_meta.read_doc_metadata(_upload_pdf())
    props = _pdf_props(tailor.render_pdf(BASE, meta))
    assert props["/Producer"] == "Microsoft Word for Microsoft 365"
    assert props["/Creator"] == "Microsoft Word"
    assert props["/Author"] == "Jane A. Doe"
    assert props["/CreationDate"].startswith("D:20240115091500")


def test_a_tailored_docx_carries_a_pdf_originals_properties():
    """The export is PDF *and* DOCX whatever the original was, so properties have to cross
    formats — a PDF upload still has to furnish the DOCX's core properties."""
    meta = doc_meta.read_doc_metadata(_upload_pdf())
    core = _docx_props(tailor.render_docx(BASE, meta))
    assert core.author == "Jane A. Doe" and core.title == "Jane Doe CV 2024"
    assert core.created.replace(tzinfo=timezone.utc) == datetime(
        2024, 1, 15, 9, 15, tzinfo=timezone.utc)


def test_no_original_means_no_toolchain_fingerprints():
    """The bar that motivated the feature: nothing the candidate sends should name the
    library that produced it, even when there was no original to copy from."""
    props = _pdf_props(tailor.render_pdf(BASE))
    assert "ReportLab" not in props.get("/Producer", "")
    assert props.get("/Creator", "") in ("", None)
    assert props["/Author"] == "Jane Doe"

    core = _docx_props(tailor.render_docx(BASE))
    assert (core.comments or "") == ""
    assert core.created.year >= 2026, "python-docx's 2013 template date reached an export"


def test_stamping_changes_the_properties_and_nothing_else():
    """The stamp is a post-pass over a finished PDF. If it disturbed the page content it
    would put the machine-readability check — the thing standing between the candidate and
    an ATS that cannot read their CV — at risk."""
    meta = doc_meta.read_doc_metadata(_upload_pdf())
    plain, stamped = tailor.render_pdf(BASE), tailor.render_pdf(BASE, meta)
    assert tailor.pdf_text(plain) == tailor.pdf_text(stamped)
    assert _pdf_props(plain)["/Author"] != _pdf_props(stamped)["/Author"]


def test_render_both_threads_the_properties_into_both_files():
    meta = doc_meta.read_doc_metadata(_upload_pdf())
    out = tailor.render_both(BASE, meta)
    assert out["pdf_machine_readable"], "stamping broke the ATS-readability guarantee"
    assert _pdf_props(out["pdf"])["/Producer"] == "Microsoft Word for Microsoft 365"
    assert _docx_props(out["docx"]).author == "Jane A. Doe"


def test_a_broken_stamp_still_returns_a_usable_pdf():
    """Properties must never cost the candidate their CV: if the rewrite fails, the render
    it was handed comes back untouched rather than an exception reaching the export."""
    rendered = tailor.render_pdf(BASE)
    assert doc_meta.stamp_pdf(b"not a pdf", {"author": "Jane"}) == b"not a pdf"
    assert doc_meta.stamp_pdf(rendered, None, name="Jane Doe")


# --------------------------------------------------------------------------- #
# The wire format (properties cross an MCP boundary as JSON)
# --------------------------------------------------------------------------- #
def test_properties_survive_a_json_round_trip():
    meta = doc_meta.read_doc_metadata(_upload_pdf())
    assert doc_meta.from_jsonable(doc_meta.to_jsonable(meta)) == meta


def test_an_unparseable_wire_timestamp_is_dropped_not_guessed():
    out = doc_meta.from_jsonable({"author": "Jane", "created": "sometime last year"})
    assert out == {"author": "Jane"}
